descriptor.templateCss:
.card {
    padding: 12px 14px;
    border: 1px solid #e6e9ef;
    border-radius: 12px;
    background: #fff
}
.ph-card {
  padding: 12px;
  font-family: Roboto, system-ui, -apple-system, Segoe UI, Arial, sans-serif;
}
.ph-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}
.ph-title {
  font-weight: 600;
  font-size: 16px;
  color: rgba(0,0,0,.87);
}
.ph-time {
  font-size: 12px;
  color: rgba(0,0,0,.54);
}

.ph-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 8px;
  margin-bottom: 12px;
}
.ph-tile {
  border: 1px solid rgba(0,0,0,.12);
  border-radius: 8px;
  padding: 10px;
  background: #fff;
}
.ph-kpi {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.2;
}
.ph-label {
  font-size: 12px;
  color: rgba(0,0,0,.65);
}
.ph-sub {
  margin-top: 4px;
  font-size: 11px;
  color: rgba(0,0,0,.54);
}

/* color accents for criticality when KPI > 0 */
#tile-fault .ph-kpi.positive,
#tile-sec .ph-kpi.positive { color: #d62828; }  /* red for faults/security */
#tile-ota  .ph-kpi.positive { color: #1f6bdd; }  /* blue for ota */
#tile-log  .ph-kpi.positive { color: #6c757d; }  /* neutral for logs */

.ph-detail .row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 8px;
  margin: 8px 0;
}
.ph-detail .col {
  border: 1px dashed rgba(0,0,0,.1);
  border-radius: 8px;
  padding: 8px;
  background: #fff;
}
.ph-detail .k {
  font-size: 11px;
  color: rgba(0,0,0,.54);
}
.ph-detail .v {
  font-size: 14px;
  font-weight: 600;
  color: rgba(0,0,0,.87);
}

/* small badges (ON/OFF) */
.badge {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 10px;
  font-size: 11px;
  background: rgba(0,0,0,.06);
  color: rgba(0,0,0,.76);
}
.badge.ok   { background: rgba(46,204,113,.18); color:#2e8b57; }
.badge.warn { background: rgba(255,193,7,.18);  color:#8a6d3b; }
.badge.err  { background: rgba(214,40,40,.18);  color:#a61d24; }

