/* Platform Health (ATM Details) — CE-safe */
self.onInit = function () {
  var root = self.ctx.$container[0];

  // DOM refs
  var elTime     = root.querySelector('.ph-time');
  var tileLog    = root.querySelector('#tile-log .ph-kpi');
  var tileLogSub = root.querySelector('#tile-log .ph-sub');
  var tileFault  = root.querySelector('#tile-fault .ph-kpi');
  var tileFaultSub = root.querySelector('#tile-fault .ph-sub');
  var tileSec    = root.querySelector('#tile-sec .ph-kpi');
  var tileSecSub = root.querySelector('#tile-sec .ph-sub');
  var tileOta    = root.querySelector('#tile-ota .ph-kpi');
  var tileOtaSub = root.querySelector('#tile-ota .ph-sub');

  var vOtaState  = root.querySelector('#ota-state');
  var vOtaProg   = root.querySelector('#ota-progress');
  var vAnomaly   = root.querySelector('#anomaly');
  var vTamper    = root.querySelector('#tamper');
  var vMalware   = root.querySelector('#malware');
  var vLastAny   = root.querySelector('#last-any');

  var DEBUG = true;
  function log(m, o){ if (DEBUG) try{console.log('[ph]', m, o||'');}catch(e){} }

  function fmt(ts) {
    if (!ts && ts !== 0) return '—';
    try { return new Date(ts).toISOString().replace('T',' ').slice(0,19); }
    catch(_){ return String(ts); }
  }

  function normKey(s) {
    return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-');
  }

  // Given data key, classify into platform-health buckets
  function classifyByKey(k) {
    switch (k) {
      case 'log-event':
      case 'ej-snippet': return 'log';
      case 'fault-event':
      case 'hw-fault':   return 'fault';
      case 'tamper-switch':
      case 'malware-detected':
      case 'anomaly-score': return 'security';
      case 'ota-state':
      case 'ota-progress-pct': return 'ota';
      default: return null;
    }
  }

  // Get "latest" value from a series (assumes aggregation NONE)
  function lastPt(series) {
    var d = series && series.data ? series.data : [];
    if (!d.length) return null;
    return d[d.length - 1];
  }

  // Convert anomaly to percent if 0..1
  function fmtAnomaly(v) {
    if (v == null) return '—';
    var n = Number(v);
    if (isNaN(n)) return String(v);
    if (n <= 1) return Math.round(n * 100) + '%';
    return Math.round(n) + '%';
  }

  // boolish helpers
  function isOn(x) {
    // treats 1/true/"1"/"true"/"on" as ON
    if (x === true || x === 1) return true;
    if (typeof x === 'string') {
      var s = x.trim().toLowerCase();
      return s === '1' || s === 'true' || s === 'on' || s === 'alarm' || s === 'detected';
    }
    return false;
  }

  function update() {
    var ds = self.ctx.data || [];
    var counts = { log:0, fault:0, security:0, ota:0 };
    var lastTs = null;

    var latest = {
      'ota-state': null,
      'ota-progress-pct': null,
      'anomaly-score': null,
      'tamper-switch': null,
      'malware-detected': null
    };

    // Count points and grab latest of the keys we care about
    for (var i=0; i<ds.length; i++) {
      var s = ds[i];
      if (!s || !s.dataKey) continue;

      var key = normKey(s.dataKey.name || s.dataKey.label || '');
      var bucket = classifyByKey(key);
      var arr = s.data || [];

      if (bucket) {
        counts[bucket] += arr.length;
        // track last timestamp for any bucket
        if (arr.length) {
          var ts = arr[arr.length-1][0];
          if (lastTs == null || ts > lastTs) lastTs = ts;
        }
      }

      // capture latest specific values (if stream exists)
      if (key in latest) {
        var pt = lastPt(s);
        latest[key] = pt ? pt[1] : null;
      }
    }

    // Header time (last event across all)
    elTime.textContent = lastTs ? ('Last event: ' + fmt(lastTs)) : 'No events in window';

    // Tile KPIs
    function setTile(elKpi, elSub, val, positiveIfVal) {
      elKpi.textContent = String(val || 0);
      elKpi.classList.toggle('positive', !!(positiveIfVal && val > 0));
      elSub.textContent = lastTs ? ('last: ' + fmt(lastTs)) : '—';
    }

    setTile(tileLog,   tileLogSub,   counts.log,     true);
    setTile(tileFault, tileFaultSub, counts.fault,   true);
    setTile(tileSec,   tileSecSub,   counts.security,true);
    setTile(tileOta,   tileOtaSub,   counts.ota,     true);

    // Detailed latest values
    vOtaState.textContent = latest['ota-state'] != null && String(latest['ota-state']).trim() !== '' ? String(latest['ota-state']) : '—';

    var prog = latest['ota-progress-pct'];
    vOtaProg.textContent = (prog == null || prog === '') ? '—' : (Number(prog).toFixed(0) + '%');

    var an = latest['anomaly-score'];
    vAnomaly.textContent = (an == null || an === '') ? '—' : fmtAnomaly(an);

    var t = latest['tamper-switch'];
    vTamper.innerHTML = (t == null)
      ? '—'
      : (isOn(t) ? '<span class="badge err">ON</span>' : '<span class="badge ok">OFF</span>');

    var m = latest['malware-detected'];
    vMalware.innerHTML = (m == null)
      ? '—'
      : (isOn(m) ? '<span class="badge err">DETECTED</span>' : '<span class="badge ok">CLEAR</span>');

    vLastAny.textContent = lastTs ? fmt(lastTs) : '—';
  }

  // Initial + update hook
  update();
  self.onDataUpdated = update;
};

